"""Рядок 5500 (власник 15.10: «ловити поломки мають тестувальниці»): чи вимкнене правило руки 2 дало ЗЛАМАНЕ МІСЦЕ на картці
(тінь суду руки 2 проти знахідок того самого правила в руці 1; різні речі в слотах правила) і, для людських вердиктів (не «Проба
РВ-6»), чи скаржились на аспект правила (`причини`, reasons/about_items dislike, «замінити» в слоті) у руці 2 і в руці 1 як базі.
Аспект і слоти — з `правило_руки2.ПЕРЕЛІК` (рядок 5502); кілька правил пари (рядок 5503) — кожне окремо.
Рядок 5508 (§2.6–2.7): лише пари із зламаним місцем; розбіжні b/c, точний знаковий тест, Вілсон, k=0, чутливість на помітних. 6.3: пара — `правило_руки2.запис_пари`; чутливість — за тестувальницею (підпис профілю), для кожного зламаного місця — повні й неповні пари. Запуск: python3 джерела/проби/рука2_зламане_місце.py [--git|файли]"""
import collections, gzip, json, os, re, subprocess, sys
from math import comb, sqrt
КОРІНЬ = os.path.dirname(os.path.dirname(os.path.dirname(os.path.abspath(__file__))))
sys.path.insert(0, os.path.join(КОРІНЬ, "джерела")); import правило_руки2 as ПР2
def файли():   # як `рука2_повтор_сукні.py`: --git — усі версії файлів вердиктів усіх гілок
    if sys.argv[1:] == ["--git"]:
        git = lambda *а: subprocess.run(("git", "-C", КОРІНЬ) + а, capture_output=True).stdout; рр = git("log", "--all", "--format=", "--raw", "--no-abbrev", "--diff-filter=AM", "--no-renames", "--", ":(glob)**/вердикти*", ":(glob)**/verdykty*").decode().splitlines()
        yield from (git("cat-file", "blob", б) for б in sorted({р.split()[3] for р in рр if р.startswith(":")})); return
    for ш in sys.argv[1:] or [os.path.join(КОРІНЬ, "аудит", "тести")]:
        for к, _, фф in (os.walk(ш) if os.path.isdir(ш) else [("", 0, [ш])]):
            yield from (open(os.path.join(к, ф), "rb").read() for ф in фф if "verdykty" in ф or "вердикти" in ф)
речі = lambda в: {r["id"]: r.get("слот") for r in в.get("речі_образу") or [] if isinstance(r, dict)}; пари, записи, гр = {}, {}, collections.defaultdict(collections.Counter)
for дані in файли():
    try: д = json.loads(gzip.decompress(дані) if дані[:2] == b"\x1f\x8b" else дані)
    except ValueError: continue
    for п in (д.get("прогони") or []) if isinstance(д, dict) else []:
        вв = {str(в.get("рука")): в for в in п.get("вердикти") or []}; сп = dict(д.get("спільне") or {}, **(п.get("спільне") or {}))
        з = ПР2.запис_пари(д, п)   # 6.3: пара — один запис; повніший виграє, коли прогін у кількох вивантаженнях
        if з and (з["прогін"] not in записи or з["повна"] and not записи[з["прогін"]]["повна"]): записи[з["прогін"]] = з
        if "1" in вв and "2" in вв: пари[(д.get("пристрій"), п.get("прогін"), вв["1"].get("склад"), вв["2"].get("склад"))] = (вв["1"], вв["2"], "Проба" in str(сп.get("профіль")), з["тестувальниця"] or "невідомо")
МАПА = {з["ід"]: (з["аспект"], з["слоти"]) for з in ПР2.ПЕРЕЛІК}
def скарга(в, аспект, слоти):   # аспект на картці чи «не ця»/dislike на речі слоту правила (без слотів — будь-якої)
    вн, рр = в.get("коментар_внутрішня") or {}, речі(в); слот = lambda і: (рр.get(і) in слоти) if слоти else і in рр
    мін = set(str(в.get("причини") or "").split("+")) | set(вн.get("reasons") or [])
    мін |= {р for і in вн.get("about_items") or [] if і.get("opinion") == "dislike" and слот(і.get("id")) for р in і.get("reasons") or [аспект]}
    return bool(аспект and аспект in мін) or any(слот(і) for і in str(в.get("замінити") or "").split("+") if і)
for в1, в2, стенд, _ in пари.values():
    if в2.get("поломка_руки") != "rule_off": continue   # стенд — вердикти скриптом: лише фізика поломки, без скарг
    for ід in str(в2.get("правило_руки") or "").split("+"):   # кілька правил пари (рядок 5503) — кожне окремо
        аспект, слоти = МАПА.get(ід, (None, ())); коди = set(ПР2.ЗА_ІД.get(ід, {}).get("коди") or [ід]); р1, р2 = речі(в1), речі(в2)
        т2 = len([з for з in в2.get("тінь_знахідки") or [] if з.get("правило") in коди]) if "тінь_знахідки" in в2 else sum(int(n) for к, n in re.findall(r"([A-Z][\w-]*)·judge\W{0,3}(\d+)", json.dumps(в2.get("тінь_правила"), ensure_ascii=False)) if к in коди)
        з1 = sum(1 for з in в1.get("знахідки_коду") or [] if з.get("правило") in коди)
        людина = all(в.get("вердикт_людини") for в in (в1, в2)) and not стенд
        c = гр["%s · %s · %s" % (ід, str(в2.get("пара_руки") or "—").split(" ·")[0], "людина" if людина else "стенд")]
        c["пар"] += 1; c["тінь суду в руці 2"] += т2 > 0; c["те саме правило говорить у руці 1"] += з1 > 0; c["тінь2 > знахідок1"] += т2 > з1
        c["речі слотів правила різні"] += bool(слоти) and {i for i, с in р1.items() if с in слоти} != {i for i, с in р2.items() if с in слоти}
        if людина: c["скарга на %s: рука 2" % аспект] += скарга(в2, аспект, слоти); c["скарга: рука 1"] += скарга(в1, аспект, слоти)
for г, c in sorted(гр.items()): print("%-34s" % г, " · ".join("%s %d" % кв for кв in c.items()))
ПОМІТНІ = {з["ід"] for з in ПР2.ПЕРЕЛІК if з.get("помітна")}   # рядок 5916: поле переліку, не ручний список
хвіст = lambda n, k: sum(comb(n, i) for i in range(k, n + 1)) / 2.0 ** n   # P(≥k із n | 50/50), однобічний
def віл(k, n):   # межі Вілсона 95 %
    if not n: return 0.0, 1.0
    p, z = k / n, 1.96; ц = (p + z * z / 2 / n) / (1 + z * z / n); пів = z * sqrt(p * (1 - p) / n + z * z / 4 / n / n) / (1 + z * z / n); return max(0.0, ц - пів), min(1.0, ц + пів)
ряд, нуль, чутл, кнуль = collections.defaultdict(collections.Counter), collections.defaultdict(collections.Counter), collections.defaultdict(collections.Counter), collections.Counter()
for в1, в2, стенд, прис in пари.values():
    if стенд: continue   # стенд — вердикти скриптом: лише фізика (гілка без скарг), у розбір скарг не йде
    людина = all(в.get("вердикт_людини") for в in (в1, в2)); прис = str(прис or "")   # 4-й елемент пари — ТЕСТУВАЛЬНИЦЯ (підпис профілю), не пристрій
    if в2.get("поломка_руки") != "rule_off":   # k=0 (рядок 5915): база хибних тривог — лише правилу, що випало б (`правило_руки` пари: жереб руки 1 без вимкнення)
        вб = [і for і in str(в1.get("правило_руки") or в2.get("правило_руки") or "").split("+") if і in МАПА]; кнуль[bool(вб)] += людина
        for ід in вб: нуль[ід]["пар"] += людина; нуль[ід]["скарга в руці 2"] += людина and скарга(в2, *МАПА[ід])
        continue
    for ід in str(в2.get("правило_руки") or "").split("+"):
        аспект, слоти = МАПА.get(ід, (None, ())); коди = set(ПР2.ЗА_ІД.get(ід, {}).get("коди") or [ід]); р1, р2 = речі(в1), речі(в2)
        т2 = len([з for з in в2.get("тінь_знахідки") or [] if з.get("правило") in коди]) if "тінь_знахідки" in в2 else sum(int(n) for к, n in re.findall(r"([A-Z][\w-]*)·judge\W{0,3}(\d+)", json.dumps(в2.get("тінь_правила"), ensure_ascii=False)) if к in коди)
        з1 = sum(1 for з in в1.get("знахідки_коду") or [] if з.get("правило") in коди)
        зламано = (т2 > 0 and т2 > з1) or (bool(слоти) and {i for i, с in р1.items() if с in слоти} != {i for i, с in р2.items() if с in слоти})   # §2.6 п.1
        c = ряд[ід]; c["пар з rule_off"] += 1
        if not (людина and зламано): c["не діяло або стенд"] += 1; continue
        s1, s2 = скарга(в1, аспект, слоти), скарга(в2, аспект, слоти); c["пар зі зламаним місцем"] += 1; c["скарга 2"] += s2; c["скарга 1"] += s1; c["b (лише в 2)"] += s2 and not s1; c["c (лише в 1)"] += s1 and not s2; c["сила тіні"] += т2
        if ід in ПОМІТНІ: ч = чутл[прис]; ч["пар"] += 1; ч["влучань"] += s2
кожне = collections.defaultdict(lambda: [0, 0, collections.Counter()])   # 6.3: зламане місце → повних пар · неповних · пропуски; людські прогони
for з in записи.values():
    for ід in (() if з["стенд"] else з["зламані_місця"]): кожне[ід][0 if з["повна"] else 1] += 1; кожне[ід][2][з["пропуск"]] += 1 if з["пропуск"] else 0
print("зламані місця (6.3): " + (" · ".join("%s повних пар %d, неповних %d%s" % (ід, a, b, " (" + ", ".join("%s %d" % кв for кв in c.items() if кв[1]) + ")" if b else "") for ід, (a, b, c) in sorted(кожне.items())) or "жодного людського прогону зі зламаним місцем"))
print("розбір скарг (рядок 5508): правил з парами rule_off %d з %d, решта — без жодної пари" % (len(ряд), len(МАПА)))
for ід in sorted(ряд):
    c, z = ряд[ід], нуль[ід]; n, b, cc = c["пар зі зламаним місцем"], c["b (лише в 2)"], c["c (лише в 1)"]; l2, u2 = віл(c["скарга 2"], n); l1, u1 = віл(c["скарга 1"], n)
    p = хвіст(b + cc, max(b, cc)) if b + cc else 1.0; верх = (c["скарга 2"] - c["скарга 1"]) / n + sqrt((c["скарга 2"] / n - l2) ** 2 + (u1 - c["скарга 1"] / n) ** 2) if n else 1.0
    вис = ("рука 2 гірша на %s: правило допомагає" % МАПА[ід][0] if b > cc else "рука 1 гірша: правило шкодить") if b + cc >= 12 and p <= 0.025 else "не впливає (верхня межа різниці %.0f%% < 10%%)" % (100 * верх) if n >= 30 and верх < 0.10 else "мало даних: розбіжних %d, пар зі зламаним місцем %d" % (b + cc, n)
    print("%-10s rule_off %2d · не діяло %2d · зламано %2d · скарги 2: %d (Вілсон %.0f–%.0f%%) 1: %d (%.0f–%.0f%%) · лише в 2 %d · лише в 1 %d · p=%.3f · тінь на пару %.1f · k=0: %d з %d (%.0f–%.0f%%) → %s" % (ід, c["пар з rule_off"], c["не діяло або стенд"], n, c["скарга 2"], 100 * l2, 100 * u2, c["скарга 1"], 100 * l1, 100 * u1, b, cc, p, c["сила тіні"] / n if n else 0, z["скарга в руці 2"], z["пар"], *(100 * x for x in віл(z["скарга в руці 2"], z["пар"])), вис))
print("k=0 (рядок 5915): людських пар без rule_off %d · з правилом, що випало б, %d (%s) · без нього %d — їм бази нема (старі файли: поломка входу до жеребу правил)" % (sum(кнуль.values()), кнуль[True], ", ".join("%s %d з %d" % (і, z["скарга в руці 2"], z["пар"]) for і, z in sorted(нуль.items()) if z["пар"]) or "none", кнуль[False]))
for пр, ч in sorted(чутл.items()): print("чутливість за тестувальницею %-8s помітних поломок %d · влучань %d (Вілсон %.0f–%.0f%%)%s" % (пр or "?", ч["пар"], ч["влучань"], *(100 * x for x in віл(ч["влучань"], ч["пар"])), " · не ловить і помітного: її мовчання про тонке правило нічого не каже" if ч["пар"] >= 3 and not ч["влучань"] else ""))
